 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f4f7fb;
       --panel: rgba(255, 255, 255, 0.92);
       --panel-border: rgba(148, 163, 184, 0.2);
       --text: #0f172a;
       --muted: #475569;
       --accent: #2563eb;
       --accent-dark: #1d4ed8;
       --input-bg: #ffffff;
       --input-border: #cbd5e1;
       --error: #dc2626;
       --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
       --radius: 22px;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
       background:
         radial-gradient(circle at top left, rgba(37, 99, 235, 0.14), transparent 28%),
         radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.16), transparent 24%),
         var(--bg);
       color: var(--text);
       display: grid;
       place-items: center;
       padding: 24px;
     }

     .page-shell {
       width: min(100%, 960px);
       display: grid;
       grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
       gap: 24px;
       align-items: stretch;
     }

     .hero,
     .form-card {
       background: var(--panel);
       border: 1px solid var(--panel-border);
       border-radius: var(--radius);
       box-shadow: var(--shadow);
       backdrop-filter: blur(14px);
     }

     .hero {
       padding: 32px;
       display: flex;
       flex-direction: column;
       justify-content: space-between;
       gap: 24px;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       width: fit-content;
       padding: 8px 12px;
       border-radius: 999px;
       background: rgba(37, 99, 235, 0.08);
       color: var(--accent);
       font-size: 0.875rem;
       font-weight: 700;
       letter-spacing: 0.02em;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 5vw, 3.25rem);
       line-height: 1.05;
     }

     .hero p {
       margin: 0;
       color: var(--muted);
       font-size: 1rem;
       line-height: 1.7;
       max-width: 34ch;
     }

     .hero-points {
       display: grid;
       gap: 12px;
       padding: 0;
       margin: 0;
       list-style: none;
     }

     .hero-points li {
       padding: 14px 16px;
       border-radius: 16px;
       background: rgba(255, 255, 255, 0.78);
       border: 1px solid rgba(148, 163, 184, 0.18);
       color: var(--text);
       font-weight: 600;
     }

     .form-card {
       padding: 32px;
     }

     .form-card h2 {
       margin: 0 0 10px;
       font-size: 1.5rem;
     }

     .form-card > p {
       margin: 0 0 24px;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 18px;
     }

     .form-field {
       display: grid;
       gap: 8px;
     }

     label {
       font-size: 0.95rem;
       font-weight: 700;
     }

     .label-note {
       color: var(--muted);
       font-weight: 500;
       font-size: 0.85rem;
       margin-left: 6px;
     }

     input {
       width: 100%;
       padding: 14px 16px;
       font: inherit;
       color: var(--text);
       background: var(--input-bg);
       border: 1px solid var(--input-border);
       border-radius: 14px;
       outline: none;
       transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
     }

     input::placeholder {
       color: #94a3b8;
     }

     input:focus {
       border-color: var(--accent);
       box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
       transform: translateY(-1px);
     }

     .helper-text,
     .error-text {
       font-size: 0.875rem;
       line-height: 1.5;
     }

     .helper-text {
       color: var(--muted);
     }

     .error-text {
       color: var(--error);
       min-height: 1.3em;
     }

     .form-field.invalid input {
       border-color: var(--error);
       box-shadow: 0 0 0 4px rgba(220, 38, 38, 0.12);
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 14px;
       padding: 15px 18px;
       font: inherit;
       font-weight: 700;
       color: #ffffff;
       background: linear-gradient(135deg, var(--accent), var(--accent-dark));
       box-shadow: 0 14px 32px rgba(37, 99, 235, 0.28);
       cursor: pointer;
       transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
     }

     button:hover,
     button:focus-visible {
       transform: translateY(-1px);
       box-shadow: 0 18px 36px rgba(37, 99, 235, 0.32);
       filter: brightness(1.02);
     }

     button:focus-visible {
       outline: 3px solid rgba(37, 99, 235, 0.22);
       outline-offset: 3px;
     }

     .status-message {
       margin: 4px 0 0;
       font-size: 0.95rem;
       font-weight: 600;
       color: #166534;
       min-height: 1.5em;
     }

     @media (max-width: 720px) {
       .hero,
       .form-card {
         padding: 24px;
       }
     }
   </style>
 </head>
 <body>
   <main class="page-shell">
     <section class="hero" aria-label="Support introduction">
       <div>
         <span class="eyebrow">Support</span>
         <h1>Get help from our team.</h1>
       </div>
       <p>
         Send us your details and a member of support will follow up with the right next step for your issue.
       </p>
       <ul class="hero-points" aria-label="Support highlights">
         <li>Fast responses for account and product questions</li>
         <li>Clear follow-up by email or phone when needed</li>
         <li>Simple, accessible contact experience</li>
       </ul>
     </section>

     <section class="form-card" aria-labelledby="contact-form-title">
       <h2 id="contact-form-title">Contact support</h2>
       <p>Required fields are marked. Phone number is optional.</p>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="full-name">
             Full name
             <span class="label-note">(required)</span>
           </label>
           <input
             id="full-name"
             name="fullName"
             type="text"
             autocomplete="name"
             placeholder="Jordan Lee"
             required
           >
           <p class="error-text" id="full-name-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="email">
             Email address
             <span class="label-note">(required)</span>
           </label>
           <input
             id="email"
             name="email"
             type="email"
             autocomplete="email"
             placeholder="jordan@example.com"
             required
           >
           <p class="error-text" id="email-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="phone">
             Phone number
             <span class="label-note">(optional)</span>
           </label>
           <input
             id="phone"
             name="phone"
             type="tel"
             autocomplete="tel"
             placeholder="(555) 123-4567"
             aria-describedby="phone-helper phone-error"
           >
           <p class="helper-text" id="phone-helper">Use digits with an area code, for example: (555) 123-4567.</p>
           <p class="error-text" id="phone-error" aria-live="polite"></p>
         </div>

         <button type="submit">Submit request</button>
         <p class="status-message" id="form-status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#support-form");
     const statusMessage = document.querySelector("#form-status");
     const hasSubmitted = { value: false };

     const fields = {
       fullName: {
         input: document.querySelector("#full-name"),
         error: document.querySelector("#full-name-error"),
         validate(value) {
           if (!value.trim()) {
             return "Enter your full name.";
           }

           return "";
         }
       },
       email: {
         input: document.querySelector("#email"),
         error: document.querySelector("#email-error"),
         validate(value) {
           if (!value.trim()) {
             return "Enter your email address.";
           }

           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value.trim())) {
             return "Enter a valid email address.";
           }

           return "";
         }
       },
       phone: {
         input: document.querySelector("#phone"),
         error: document.querySelector("#phone-error"),
         validate(value) {
           const trimmed = value.trim();
           if (!trimmed) {
             return "";
           }

           const phonePattern = /^\+?[0-9\s().-]{10,20}$/;
           if (!phonePattern.test(trimmed)) {
             return "Use a valid phone number format.";
           }

           return "";
         }
       }
     };

     function renderFieldState(fieldConfig, message) {
       const wrapper = fieldConfig.input.closest(".form-field");
       fieldConfig.error.textContent = message;
       fieldConfig.input.setAttribute("aria-invalid", message ? "true" : "false");
       wrapper.classList.toggle("invalid", Boolean(message));
     }

     function validateField(fieldConfig) {
       const message = fieldConfig.validate(fieldConfig.input.value);
       renderFieldState(fieldConfig, message);
       return !message;
     }

     Object.values(fields).forEach((fieldConfig) => {
       fieldConfig.input.addEventListener("blur", () => {
         if (hasSubmitted.value) {
           validateField(fieldConfig);
         }
       });

       fieldConfig.input.addEventListener("input", () => {
         if (hasSubmitted.value) {
           validateField(fieldConfig);
         }
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       hasSubmitted.value = true;
       statusMessage.textContent = "";

       const isValid = Object.values(fields).every((fieldConfig) => validateField(fieldConfig));

       if (!isValid) {
         return;
       }

       statusMessage.textContent = "Thanks. Your support request is ready to send.";
       form.reset();
       hasSubmitted.value = false;

       Object.values(fields).forEach((fieldConfig) => {
         renderFieldState(fieldConfig, "");
       });
     });
   </script>
 </body>
 </html>

